generated_sql:
SELECT SUM(CASE WHEN LOWER(label) = '+' THEN 1 ELSE 0 END) AS total_carcinogenic_molecules
FROM molecule
WHERE molecule_id >= 'TR000' AND molecule_id <= 'TR030';

SELECT CAST(SUM(CASE WHEN LOWER(bond_type) = '=' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT c.type AS card_type
FROM cards c
WHERE LOWER(c.name) = 'benalish knight';

SELECT p.OwnerDisplayName AS Owner, p.LastEditorDisplayName AS Editor
FROM posts p
WHERE LOWER(p.Title) = LOWER('open source tools for visualizing multi-dimensional data?');

SELECT SUM(p.Score) AS total_score
FROM posts p
WHERE strftime('%Y-%m-%d', p.LasActivityDate) = '2010-07-19';

SELECT CAST(SUM(CASE WHEN LOWER(g.gender) = 'male' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN LOWER(g.gender) = 'female' THEN 1 ELSE 0 END), 0) AS ratio
FROM superhero s
JOIN gender g ON s.gender_id = g.id;

SELECT superhero_name 
FROM superhero 
WHERE LOWER(full_name) = 'charles chandler';

SELECT 
    (SELECT code FROM drivers ORDER BY dob DESC LIMIT 3) AS top_3_codes,
    (SELECT COUNT(*) FROM drivers WHERE nationality IN ('Netherlands', 'Netherland') AND driverId IN (SELECT driverId FROM drivers ORDER BY dob DESC LIMIT 3)) AS netherlandic_count;

SELECT CAST(COUNT(*) AS REAL) / 10.0 AS annual_average_races
FROM races
WHERE year >= 2000 AND year <= 2009;

SELECT CAST(SUM(CASE WHEN LOWER(preferred_foot) = 'left' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(player_fifa_api_id) AS percentage
FROM Player_Attributes
WHERE strftime('%Y', date) BETWEEN '1987' AND '1992';

SELECT AVG(CAST(COUNT(*) AS REAL) / CAST(COUNT(DISTINCT event_name) AS REAL)) AS average_attendance
FROM event
WHERE type = 'Meeting' AND strftime('%Y', event_date) = '2020';

SELECT m.first_name || ' ' || m.last_name AS full_name, m.email
FROM member m
WHERE LOWER(m.position) = 'secretary';

SELECT CAST(SUM(CASE WHEN Segment = 'LAM' AND Consumption > 46.73 THEN 1 ELSE 0 END) AS REAL) * 100.0 / SUM(CASE WHEN Segment = 'LAM' THEN 1 ELSE 0 END) AS percentage
FROM customers
JOIN "yearmonth" ON customers.CustomerID = "yearmonth".CustomerID;

SELECT CAST(SUM(CASE WHEN Consumption > 528.3 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage
FROM yearmonth
WHERE strftime('%Y-%m', Date) = '2012-02';
